def max_value_on_paths(N: int, grid_values) -> int:
    # Build value map
    val = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, v in grid_values:
        if x == 0 and y == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            val[x][y] = v

    NEG = -10**18
    # dp[x1][x2] = max value when both walkers are at (x1, y1) and (x2, y2) respectively
    dp_prev = [[NEG] * (N + 1) for _ in range(N + 1)]
    # Start at (1,1) for both
    dp_prev[1][1] = val[1][1]

    steps = 2 * N - 2
    for step in range(1, steps + 1):
        dp_cur = [[NEG] * (N + 1) for _ in range(N + 1)]
        for x1 in range(1, N + 1):
            y1 = step + 2 - x1
            if y1 < 1 or y1 > N:
                continue
            for x2 in range(1, N + 1):
                y2 = step + 2 - x2
                if y2 < 1 or y2 > N:
                    continue
                cur_val = val[x1][y1]
                if x1 != x2 or y1 != y2:
                    cur_val += val[x2][y2]
                best = NEG
                # Previous step positions: each moved down or right
                for dx1 in (0, 1):
                    prev_x1 = x1 - dx1
                    prev_y1 = y1 - (1 - dx1)
                    if prev_x1 < 1 or prev_y1 < 1:
                        continue
                    for dx2 in (0, 1):
                        prev_x2 = x2 - dx2
                        prev_y2 = y2 - (1 - dx2)
                        if prev_x2 < 1 or prev_y2 < 1:
                            continue
                        prev = dp_prev[prev_x1][prev_x2]
                        if prev > best:
                            best = prev
                if best != NEG:
                    dp_cur[x1][x2] = best + cur_val
        dp_prev = dp_cur

    return dp_prev[N][N] if dp_prev[N][N] != NEG else 0

def max_product(num_str: str, N: int, K: int) -> int:
    # Ensure N matches length of num_str, adjust if needed
    N = len(num_str)
    # Cannot insert more multiplication signs than gaps
    if K > N - 1:
        K = N - 1
    if K < 0:
        return 0
    # Quick return if no multiplication signs
    if K == 0:
        return int(num_str)
    # Precompute integer values for all substrings
    nums = [[0] * (N + 1) for _ in range(N)]
    for i in range(N):
        val = 0
        for j in range(i, N):
            val = val * 10 + int(num_str[j])
            nums[i][j + 1] = val
    # dp[i][k] = max product for first i digits using k multiplication signs
    dp = [[0] * (K + 1) for _ in range(N + 1)]
    # Base case: 0 signs
    for i in range(1, N + 1):
        dp[i][0] = nums[0][i]
    # Fill DP for k >= 1
    for i in range(1, N + 1):
        max_k = min(K, i - 1)  # can only place at most i-1 signs in i digits
        for k in range(1, max_k + 1):
            best = 0
            # last segment starts at position j (0-indexed) up to i-1
            # need j >= k because first j digits must accommodate k-1 signs
            for j in range(k, i):
                prod = dp[j][k - 1] * nums[j][i]
                if prod > best:
                    best = prod
            dp[i][k] = best
    return dp[N][K]

