    if len(parts) != 4:
        return isbn
    digits_str = parts[0] + parts[1] + parts[2]
    if len(digits_str) != 9 or not digits_str.isdigit():
        return isbn
    digits = [int(d) for d in digits_str]
    weighted_sum = sum((10 - i) * d for i, d in enumerate(digits))
    checksum_val = (11 - (weighted_sum % 11)) % 11
