def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for idx, coeff in enumerate(coeffs):
        deg = n - idx
        if coeff == 0:
            continue

        # Determine sign
        if not terms:
            sign = '' if coeff > 0 else '-'
        else:
            sign = '+' if coeff > 0 else '-'

        abs_coef = abs(coeff)

        # Variable part
        if deg > 1:
            var = f'x^{deg}'
        elif deg == 1:
            var = 'x'
        else:
            var = ''

        # Coefficient part
        if abs_coef == 1 and var:
            coef_part = ''
        else:
            coef_part = str(abs_coef)

        term = f"{sign}{coef_part}{var}"
        terms.append(term)

    if not terms:
        return '0'
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    mapping = {}
    rev = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            if o in rev and rev[o] != e:
                return "Failed"
            mapping[e] = o
            rev[o] = e
    if len(mapping) != 26:
        return "Failed"
    decoded = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded.append(mapping[ch])
    return "".join(decoded)

def largest_prime_factor(n: int) -> int:
    i = 2
    while i * i <= n:
        if n % i == 0:
            return n // i
        i += 1 if i == 2 else 2
    return n

def count_coprime_pairs(x0: int, y0: int) -> int:
    if y0 % x0 != 0:
        return 0
    N = y0 // x0
    count = 0
    import math
    for a in range(1, int(math.isqrt(N)) + 1):
        if N % a == 0:
            b = N // a
            if math.gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
    return count

def preorder_traversal(inorder: str, postorder: str) -> str:
    idx_map = {ch: i for i, ch in enumerate(inorder)}

    def helper(in_left: int, in_right: int, post_left: int, post_right: int) -> str:
        if in_left >= in_right:
            return ''
        root_val = postorder[post_right - 1]
        root_idx = idx_map[root_val]
        left_size = root_idx - in_left
        left_pre = helper(in_left, root_idx, post_left, post_left + left_size)
        right_pre = helper(root_idx + 1, in_right, post_left + left_size, post_right - 1)
        return root_val + left_pre + right_pre

    return helper(0, len(inorder), 0, len(postorder))

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    from collections import deque
    if A == B:
        return 0
    visited = {A}
    queue = deque([(A, 0)])
    while queue:
        current, steps = queue.popleft()
        if steps >= 10:
            continue
        for src, tgt in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_string = current[:idx] + tgt + current[idx + len(src):]
                if new_string == B:
                    return steps + 1
                if new_string not in visited:
                    visited.add(new_string)
                    queue.append((new_string, steps + 1))
                start = idx + 1  # allow overlapping matches
    return "NO ANSWER!"

def is_prime(num: int) -> bool:
    """Return True if num is a prime number, False otherwise."""
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules) -> int:
    from collections import deque

    # Build mapping from digit to list of possible transformed digits
    transform = {}
    for x, y in rules:
        transform.setdefault(str(x), []).append(str(y))

    start = str(n)
    visited = {start}
    queue = deque([start])

    while queue:
        num = queue.popleft()
        for i, d in enumerate(num):
            if d not in transform:
                continue
            for y in transform[d]:
                new_num = num[:i] + y + num[i+1:]
                if new_num not in visited:
                    visited.add(new_num)
                    queue.append(new_num)

    return len(visited)

