                continue
            stmt_clean = stmt.strip().rstrip('.').lower()
            truth = None
            if stmt_clean == "i am guilty":
                truth = (speaker_upper == scenario_upper)
            elif stmt_clean == "i am not guilty":
                truth = (speaker_upper != scenario_upper)
            elif stmt_clean.endswith(" is guilty"):
                subject = stmt_clean.split(" is guilty")[0].strip()
                truth = (subject.upper() == scenario_upper)
            elif stmt_clean.endswith(" is not guilty"):
                subject = stmt_clean.split(" is not guilty")[0].strip()
                truth = (subject.upper() != scenario_upper)
            else:
                continue
            if truth is None:
                continue
            if speaker_upper in liar_set:
                if truth:
                    return False
            else:
                if not truth:
                    return False
    return True

