def mod_inverse(a, b):
    """Return the modular multiplicative inverse of a modulo b using the extended Euclidean algorithm.
    If the inverse does not exist (i.e., gcd(a, b) != 1), return None.
    """
    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        else:
            g, x1, y1 = extended_gcd(y, x % y)
            return (g, y1, x1 - (x // y) * y1)

    if b <= 0:
        raise ValueError("Modulus must be a positive integer")
    g, x, _ = extended_gcd(a, b)
    if g != 1:
        return None
    return x % b

