def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0
    # Longest strictly increasing subsequence ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1
    # Longest strictly decreasing subsequence starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1
    # Maximum length of a bitonic subsequence
    best = 0
    for i in range(n):
        # peak at i; combine inc ending at i and dec starting at i, subtract 1 to avoid double counting i
        best = max(best, lis[i] + lds[i] - 1)
    # Minimum removals
    return n - best
